CREATE VIEW v_Examination_Laboratory_Patient AS SELECT Examination.ID AS ID, Examination.`Examination Date` AS `Examination Date`, Examination.`aCL IgG` AS `aCL IgG`, Examination.`aCL IgM` AS `aCL IgM`, Examination.ANA AS ANA, Examination.`ANA Pattern` AS `ANA Pattern`, Examination.`aCL IgA` AS `aCL IgA`, Examination.Diagnosis AS Diagnosis, Examination.KCT AS KCT, Examination.RVVT AS RVVT, Examination.LAC AS LAC, Examination.Symptoms AS Symptoms, Examination.Thrombosis AS Thrombosis, Patient.SEX AS Patient_SEX, Patient.Birthday AS Patient_Birthday, Patient.Description AS Patient_Description, Patient.`First Date` AS `Patient_First Date`, Patient.Admission AS Patient_Admission, Patient.Diagnosis AS Patient_Diagnosis, Laboratory.Date AS Laboratory_Date, Laboratory.GOT AS Laboratory_GOT, Laboratory.GPT AS Laboratory_GPT, Laboratory.LDH AS Laboratory_LDH, Laboratory.ALP AS Laboratory_ALP, Laboratory.TP AS Laboratory_TP, Laboratory.ALB AS Laboratory_ALB, Laboratory.UA AS Laboratory_UA, Laboratory.UN AS Laboratory_UN, Laboratory.CRE AS Laboratory_CRE, Laboratory.`T-BIL` AS `Laboratory_T-BIL`, Laboratory.`T-CHO` AS `Laboratory_T-CHO`, Laboratory.TG AS Laboratory_TG, Laboratory.CPK AS Laboratory_CPK, Laboratory.GLU AS Laboratory_GLU, Laboratory.WBC AS Laboratory_WBC, Laboratory.RBC AS Laboratory_RBC, Laboratory.HGB AS Laboratory_HGB, Laboratory.HCT AS Laboratory_HCT, Laboratory.PLT AS Laboratory_PLT, Laboratory.PT AS Laboratory_PT, Laboratory.APTT AS Laboratory_APTT, Laboratory.FG AS Laboratory_FG, Laboratory.PIC AS Laboratory_PIC, Laboratory.TAT AS Laboratory_TAT, Laboratory.TAT2 AS Laboratory_TAT2, Laboratory.`U-PRO` AS `Laboratory_U-PRO`, Laboratory.IGG AS Laboratory_IGG, Laboratory.IGA AS Laboratory_IGA, Laboratory.IGM AS Laboratory_IGM, Laboratory.CRP AS Laboratory_CRP, Laboratory.RA AS Laboratory_RA, Laboratory.RF AS Laboratory_RF, Laboratory.C3 AS Laboratory_C3, Laboratory.C4 AS Laboratory_C4, Laboratory.RNP AS Laboratory_RNP, Laboratory.SM AS Laboratory_SM, Laboratory.SC170 AS Laboratory_SC170, Laboratory.SSA AS Laboratory_SSA, Laboratory.SSB AS Laboratory_SSB, Laboratory.CENTROMEA AS Laboratory_CENTROMEA, Laboratory.DNA AS Laboratory_DNA, Laboratory.`DNA-II` AS `Laboratory_DNA-II` FROM Examination LEFT JOIN Patient AS Patient ON Examination.ID = Patient.ID LEFT JOIN Laboratory AS Laboratory ON Patient.ID = Laboratory.ID;
